window.STORY_CHAPTERS["c2fb93ab2f9e218e9"]={"id":"c2fb93ab2f9e218e9","lines":[{"uid":"talk.vc.home_wait_sortiliena_1st_3#originalText","id":"talk.vc.home_wait_sortiliena_1st_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"即使许多事物改变了，你还是一直没有变呢，就跟初次见面时一样。","en":"Everything changes, but not you. You're just like you were when I first met you.","ja":"色んなものが変わってもお前はずっと変わらないな初めて会った頃のままだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sortiliena_1st_4#originalText","id":"talk.vc.home_wait_sortiliena_1st_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"能成为你的指导生，是我这辈子最骄傲的事。","en":"Being your mentor is one of my proudest life achievements.","ja":"お前の指導生になれたことは私にとって、生涯で最も誇らしい出来事だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sortiliena_1st_9#originalText","id":"talk.vc.home_wait_sortiliena_1st_9","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"又在打什么主意了对吧？你安静的时候，多半是想到了什么。","en":"You're up to something again. When you get quiet, I know the wheels in your mind are spinning.","ja":"また何かを企んでいるな?お前が静かな時は大抵何かを思いついた時だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1st_1#originalText","id":"talk.vc.home_touch_sortiliena_1st_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"长大以后就没被摸过头了……总觉得有些害羞呢。","en":"No one has patted my head since I was a child... It is somewhat embarrassing.","ja":"頭を撫でられるなど子どもの頃以来だ……なんだか照れくさいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1st_2#originalText","id":"talk.vc.home_touch_sortiliena_1st_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"别看我这样，我也是个女孩子，可是有好好保养头发的。","en":"I may not act it, but I do consider myself a woman. I must take care of my hair.","ja":"こう見えても、私だって女性の端くれだ髪の手入れは欠かさん"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1st_4#originalText","id":"talk.vc.home_touch_sortiliena_1st_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽然已经努力锻炼了，但力量还是比不上男性剑士……","en":"No matter how hard I train, I never seem to develop muscles like a male swordsman would.","ja":"男の剣士に比べるとどうしても筋力は劣ってしまうこれでも鍛えているのだが……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1st_5#originalText","id":"talk.vc.home_touch_sortiliena_1st_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽然我喜欢你，也很敬佩你……但不要随便就做这种事。","en":"I do like and respect you... but stop doing things so lightly.","ja":"お前のことは好きだし尊敬もしているが……軽々しくそういうことをするな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1st_6#originalText","id":"talk.vc.home_touch_sortiliena_1st_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这次可不会再让你逃走了。我要好好让你明白这种行为的后果！","en":"You won't escape this time! I will make you pay dearly for your actions!","ja":"今度という今度は逃がさないぞその行為の意味、しかとわからせてやる!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_1st_1#originalText","id":"talk.vc.home_time_sortiliena_1st_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"晨练很累吧？我准备了简单的餐点，来吃吧。","en":"You must be tired from your morning training. I've prepared a light breakfast, so eat up.","ja":"朝練、疲れただろう?軽い食事を用意しておいたさあ、食べてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_1st_4#originalText","id":"talk.vc.home_time_sortiliena_1st_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你有空吗？方便的话，陪我去街上买东西吧。","en":"Do you have some time? If so, might I suggest we go into town for some shopping?","ja":"少し時間はあるか?よかったら、一緒に街へ買い物に行こう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_1st_7#originalText","id":"talk.vc.home_time_sortiliena_1st_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"又在练剑了吗？真令人佩服呢。好，我也一起来练吧。","en":"Still swinging your sword, eh? It really is commendable. Alright, I think I'll join you.","ja":"まだ剣を振っているのか感心だな。よし、私も一緒にやろうじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_1st_10#originalText","id":"talk.vc.home_time_sortiliena_1st_10","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我们两个失眠好伙伴一起散个步吧。别担心，被发现就说指导生命令的就好了。","en":"I can't sleep either. Let's go for a walk. If we're caught, just say you were following orders.","ja":"眠れない者同士、散歩でもするか。なに、見つかったら指導生命令だと言えばいい"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_1st_1#originalText","id":"talk.vc.home_day_sortiliena_1st_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"怎么了？瞧你一脸睡意。好，我就让你好好清醒过来。拿剑吧！","en":"What's wrong? You look sleepy. Well, I know how to wake you up. Grab your sword!","ja":"どうした、眠そうな顔だなよし、目を覚ましてやろう剣を取れ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_1st_2#originalText","id":"talk.vc.home_day_sortiliena_1st_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你一天比一天强了。我很期待看到你每次的成长呢。","en":"You're getting stronger by the day. And it brings me joy watching you grow.","ja":"お前は日々強くなっているそれを見るのを、私は楽しみにしているんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_1st_3#originalText","id":"talk.vc.home_day_sortiliena_1st_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"安息日可别练剑喔。要是被发现可就麻烦了。","en":"Don't train on a Day of Rest, you hear? If you're caught, that would be a hassle.","ja":"安息日に剣を振るなよ?見つかったら、少しばかり厄介なことになるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_1st_4#originalText","id":"talk.vc.home_day_sortiliena_1st_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"有好好休息了吗？那明天继续一起加油也没问题吧。","en":"Did you rest up? Good. Then we can get back to training hard tomorrow.","ja":"十分に休めたか?なら、明日からも一緒に頑張れるな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_1st_1#originalText","id":"talk.vc.home_season_sortiliena_1st_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"每到春天，看到孩子们在外头开心地玩耍，我的心情也会跟着愉快起来。","en":"When spring comes, children love to play outside. Seeing that brings me joy.","ja":"春になると、子どもたちが外に出て楽しそうに遊ぶんだそれを見ると、こちらも楽しい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_1st_2#originalText","id":"talk.vc.home_season_sortiliena_1st_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"夏天的天气会影响秋天的收成，所以我会不自觉地在意。","en":"Summer weather affects the autumn harvest, so I always pay attention to it.","ja":"夏の天気は、秋の収穫に影響するんだだからつい気にしてしまう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_1st_3#originalText","id":"talk.vc.home_season_sortiliena_1st_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"天气稍微变冷了，记得注意保暖啊。要是生病可就麻烦了。","en":"It's gotten a bit cold, so you need to keep yourself warm. Falling ill would be a nuisance.","ja":"少し寒くなってきたが十分に暖かくするんだぞ病気になると厄介だ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_1st_4#originalText","id":"talk.vc.home_season_sortiliena_1st_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"冬季的天空总觉得看起来很遥远，明明是跟平常一样的天空。","en":"The sky always seems clearer in the winter. Strange, since it certainly is the same sky.","ja":"冬は、空が遠くまで見える気がするいつもと変わらない空のはずなのに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_1#originalText","id":"talk.vc.home_wait_yuuki_alo_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"像这样在石碑上刻下名字，就会有一种大家一直在一起的感觉。","en":"Having our names engraved on the monument like this, feels like we'll always be together.","ja":"こうやって石碑に名前が刻まれるとさ、みんなずっと一緒だ、って感じがするんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_2#originalText","id":"talk.vc.home_wait_yuuki_alo_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"呐，下次我们来一次空战吧！我觉得一定会很开心的！","en":"Hey, let's try out air combat next time! I think it will be very fun!","ja":"ねえ、今度は空中戦で戦ってみようよ!きっと楽しいと思うんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_1#originalText","id":"talk.vc.home_touch_yuuki_alo_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嘿嘿，虽然发色不一样，但是长度跟你的差不多。总觉得有点开心。","en":"Hehehe! The color is different, but my hair length is about the same as yours! It's such an honor!","ja":"えへへ、髪の色は違うけど長さはキミと同じくらいだよねなんか、うれしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_4#originalText","id":"talk.vc.home_touch_yuuki_alo_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……怎么样？我的体温有传达到你那里吗？","en":"...How is it? Can you feel my body heat?","ja":"……どう?ボクの体温キミに伝わってるかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_5#originalText","id":"talk.vc.home_touch_yuuki_alo_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我觉得……女生之间这样真的好吗……","en":"I wonder if it's ok to do this between girls... ","ja":"女の子同士でこういうのってどうなんだろうって……思うけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_1#originalText","id":"talk.vc.home_time_yuuki_alo_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"早安！嘿嘿，从早上就能够看到妳真是太幸运了！","en":"Morning! Hehe! I must be so lucky to see your face this early in the morning!","ja":"おはよー!えへへ、朝からキミの顔が見られるなんて、ラッキー!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_4#originalText","id":"talk.vc.home_time_yuuki_alo_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"呐，下次我们一起参加每个月的比武大会吧！","en":"Hey, let's participate in the next monthly tournament!","ja":"ねえ、次の月例大会は一緒に参加しようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_7#originalText","id":"talk.vc.home_time_yuuki_alo_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"差不多该去吃饭了吧。对了，也叫一下沉睡骑士的大家吧！","en":"Should we get ready to eat? Alright, let's call out all of the Sleeping Knights!","ja":"そろそろご飯にしようかそうだ、スリーピングナイツのみんなも呼ぼうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_10#originalText","id":"talk.vc.home_time_yuuki_alo_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我觉得像这样待在黑暗之中，就好像这世界只剩下你和我两个人一样。","en":"Being like this in the middle of the dark with you feels like we are the only ones in the whole world.","ja":"真っ暗な中でこうしていると世界にキミとボクのふたりしかいないみたいな、そんな気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_1#originalText","id":"talk.vc.home_day_yuuki_alo_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"新的一周开始了呢！像这样可以迎接新的一个星期，我觉得很开心喔！","en":"It's the start of a new week! Waking up to a new week like this makes me so happy!","ja":"新しい一週間の始まりだね!こうして新しい週を迎えられてボク、すごくうれしいんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_2#originalText","id":"talk.vc.home_day_yuuki_alo_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"总觉得你没什么精神耶？上学累了？来，提起精神嘛！","en":"Hey, you don't look so great? Was school busy? Hey, cheer up!","ja":"なんか元気ないなあ?学校疲れ?ほら、元気だそうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_3#originalText","id":"talk.vc.home_day_yuuki_alo_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"放假的日子就可以像这样整天跟你在一起，所以我很喜欢假期喔。","en":"I like spending a whole vacation day with you like this!","ja":"休みの日は、こうやって一日中キミと一緒にいられるから、好きなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_4#originalText","id":"talk.vc.home_day_yuuki_alo_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"明天开始就要上学了吧？呐，下次再跟我说说学校的趣事吧！","en":"School starts tomorrow, right? Hey, tell me something funny about your school again!","ja":"明日から学校だよね?ねえ、また学校の面白い話を聞かせてよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_alo_1#originalText","id":"talk.vc.home_season_yuuki_alo_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"雪溶化的地方长出了新芽！……生命力真强！","en":"When the snow melts, new sprouts will grow! ...What amazing vitality!","ja":"雪が溶けたところから新芽が生えてきてる!……すごい生命力だよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_alo_2#originalText","id":"talk.vc.home_season_yuuki_alo_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"等到夏天，我想找很多认识的人，一起办个烧烤大会！","en":"When it's summer, I want to do BBQ again! Let's invite a lot of people!","ja":"夏になったら、バーベキューやりたいなあ知り合いを大勢集めて!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_alo_3#originalText","id":"talk.vc.home_season_yuuki_alo_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我没尝过多少秋天的美味，下次你能做给我吃吗？","en":"I've never really experienced autumn flavors before, so could you make me some next time?","ja":"秋の味覚って、あんまり味わったことがなくて今度作ってくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_alo_4#originalText","id":"talk.vc.home_season_yuuki_alo_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我虽然很怕冷，但是我很喜欢下雪的晚上。大家都很安静、很温柔。","en":"I'm not that great with the cold, but I like snowy nights. Everyone feels calm and gentle.","ja":"寒いのは苦手だけど雪の夜はちょっと好きなんだみんな静かで、優しい気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_yuuki_halloween_wait_1#originalText","id":"talk.vc.home_yuuki_halloween_wait_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"快要到扮装派对了！你要扮成什么喔？","en":"It's almost time for the costume party! Do you know what you're going to be?","ja":"もうすぐ仮装パーティだよ!どんな仮装するの??"},"kind":"dialogue"},{"uid":"talk.vc.home_yuuki_halloween_wait_2#originalText","id":"talk.vc.home_yuuki_halloween_wait_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"不给糖，就要捣蛋啰～！","en":"Trick or treat, smell my feet, give me something good to eat!","ja":"お菓子くれなきゃいたずらしちゃうぞ～!"},"kind":"dialogue"},{"uid":"talk.vc.home_yuuki_halloween_wait_3#originalText","id":"talk.vc.home_yuuki_halloween_wait_3","speaker":{"cn":"有纪","ja":"ユウキ"},"text":{"cn":"Trick or Treat！","ja":"トリック・オア・トリート!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_1st_1#originalText","id":"talk.vc.home_wait_yuuki_1st_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嘿嘿，今天也见到妳了！","en":"Hehe, good to see you again today!","ja":"へへ、今日もキミに会えた!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_1st_2#originalText","id":"talk.vc.home_wait_yuuki_1st_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天要去哪走走呢？只要是跟妳一起，去哪我都可以喔！","en":"Wanna go out somewhere today? I'm cool with anywhere as long as you're with me!","ja":"今日はどこに行こうか?キミと一緒なら、ボクはどこでもいいよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_1st_3#originalText","id":"talk.vc.home_wait_yuuki_1st_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我最近精神很不错呢。因为每天都很开心啊！嘿嘿……","en":"I've been feeling really good lately. I mean, I'm just so happy every day! Hehehe...","ja":"最近はすっごく元気なんだだって、毎日嬉しいからね!……えへへ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_1st_4#originalText","id":"talk.vc.home_wait_yuuki_1st_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"不论是谁都有无可取代的事物。对我来说，那就是与伙伴们在这里的回忆。","en":"Everyone has something they'd never surrender. For me, it's the memories I made with my friends.","ja":"誰にだって譲れないものがあるボクにとって、それはここでの仲間たちとの思い出なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_1st_9#originalText","id":"talk.vc.home_wait_yuuki_1st_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"像这样两个人静静地在一起……感觉也不错呢。","en":"Just being with you quietly like this... For some reason, I don't mind it.","ja":"……こうやって、ふたりで静かにいるのも、なんだか悪くない気がしてきた"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1st_1#originalText","id":"talk.vc.home_touch_yuuki_1st_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我的身高是不是比妳矮了一点啊……唔唔，真想追上啊──","en":"Looks like I'm a little shorter. Argh, I've got some catching up to do!","ja":"ボクの方が、少し背が小さいかなあ……うう、追いつきたいよー"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1st_2#originalText","id":"talk.vc.home_touch_yuuki_1st_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我很少编头发……下次妳能帮我编吗？","en":"I've never really had my hair braided before. Will you do it for me?","ja":"髪の編み込みってあんまりやったことなくて……今度やってくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1st_4#originalText","id":"talk.vc.home_touch_yuuki_1st_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳要这样戳的话……嘿！妳看，抓到妳了！","en":"If you're gonna keep poking me like that... Yah! There, now you're miiine!","ja":"そうやって、つっついてくるなら……えい!ほら、つかまえたー!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1st_5#originalText","id":"talk.vc.home_touch_yuuki_1st_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我现在心脏一直扑通扑通跳，真是害羞耶……妳感觉得出来，对吧？","en":"My heart is racing right now... Gosh, I feel so silly... It's obvious, right?","ja":"ボク、今すっごくドキドキしてるから、恥ずかしいな……わかっちゃう、でしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1st_6#originalText","id":"talk.vc.home_touch_yuuki_1st_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"被妳摸的地方总觉得有点痒……稍微热热的。","en":"Where you touched me... It's tingling a little... and it feels kinda warm.","ja":"キミに触られたところなんだかくすぐったくて……ちょっと熱いんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_1st_1#originalText","id":"talk.vc.home_time_yuuki_1st_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"听说早餐美味的日子会有好事发生唷！","en":"You know what they say! If your breakfast tastes good, you're gonna have a great day!","ja":"朝ご飯がおいしい日はいいことがあるんだって!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_1st_4#originalText","id":"talk.vc.home_time_yuuki_1st_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"已经是午休时间了吗……那么今天就在树上一起休息吧！","en":"Time for lunch already? Okay then, let's climb that tree and spend our break there!","ja":"もうお昼の時間か……それじゃ、今日は樹の上で一緒に休憩しようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_1st_7#originalText","id":"talk.vc.home_time_yuuki_1st_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"虽然夜晚让人感觉有点寂寞，但只要跟妳在一起就不会了。","en":"Nights always feel kinda lonely. But not when you're around.","ja":"夜って、少し寂しい時間だけどキミと一緒ならそうでもない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_1st_10#originalText","id":"talk.vc.home_time_yuuki_1st_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……欸，妳还没睡吗？我也醒来了。","en":"Hey... Are you awake? Yeah, I can't sleep either.","ja":"……ね、起きてる?ボクも、目が覚めちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_1st_1#originalText","id":"talk.vc.home_day_yuuki_1st_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"听人家说，星期一上学让人心情忧郁，我倒是觉得会很开心呢。","en":"Most people hate going back to school on Monday, but that sounds like fun to me.","ja":"月曜日の学校は憂鬱って聞くけど、ボクには楽しそうに見えるなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_1st_2#originalText","id":"talk.vc.home_day_yuuki_1st_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我也有稍微念点书的唷。嘿嘿，念书很有趣呢！","en":"I'm studying a little bit on my own, you know. Hehe. Learning sure is fun!","ja":"ボクも少しだけ勉強してるんだへへ、勉強って楽しいね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_1st_3#originalText","id":"talk.vc.home_day_yuuki_1st_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天休息时要一直跟我在一起唷！打勾勾！","en":"You're spending all your time off with me today, okay? Pinky-swear!","ja":"今日のお休みは、ずっとボクと一緒ね!ゆびきり!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_1st_4#originalText","id":"talk.vc.home_day_yuuki_1st_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"总觉得就这样睡了很可惜呢。不过，很期待明天还能见到妳。","en":"I don't want to fall asleep... But then again, I can't wait to see you again when I wake up.","ja":"寝ちゃうのがもったいないなでも、また明日キミに会えるのは楽しみ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_1st_1#originalText","id":"talk.vc.home_season_yuuki_1st_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"一到春天，就会有「接下来这一年要好好努力」的感觉呢。","en":"When spring comes, I always feel inspired to keep going.","ja":"春が来ると、また一年頑張るぞって、そういう気持ちになるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_1st_2#originalText","id":"talk.vc.home_season_yuuki_1st_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"好想再去夏天的海水浴场喔。大家一起玩打西瓜跟沙滩球！","en":"I'd love to go to the beach again this summer. I wanna smash watermelons and hit beach balls.","ja":"夏の海水浴、また行きたいなあみんなでスイカ割りしてビーチボールで遊ぶんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_1st_3#originalText","id":"talk.vc.home_season_yuuki_1st_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我也喜欢开在秋天的花朵。就算在寒冷中也努力绽放的模样，忍不住想替它加油！","en":"I love autumn flowers. When I see them defying the cold to bloom, I can't help but root for them.","ja":"秋に咲く花も好き寒いけど頑張って咲いてて応援したくなっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_1st_4#originalText","id":"talk.vc.home_season_yuuki_1st_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳看，下雪了！一片雪白真是美啊……","en":"Look, it's snowing! So pretty and white...","ja":"ほら、雪が降ってるよ!真っ白で、綺麗だなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"没想到我居然能像这样和妳一起睡觉……真的像是在做梦一样。","en":"Look at us, sleeping side by side... It's really a dream come true.","ja":"君とこんな風に、一緒に寝られる日が来るなんて……本当に、夢みたいだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"心跳越来越快了。因为竟然能和妳两个人，在……这种地方……","en":"This is making me kinda nervous. I mean, I'm alone. With you. In a place...like this.","ja":"なんだか、ドキドキしちゃうよだって、君とふたりっきりでこんな……場所で……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我可以……再靠近妳一点吗？","en":"Hey, can I scoot closer to you?","ja":"ねえ、もう少しだけ……そっちに行ってもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_4#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天的妳就像换了个人一样漂亮。啊！妳一直都很漂亮，但今天特别漂亮……","en":"You're so pretty I don't recognize you...oh! I mean, you're always pretty, it's just...extra special.","ja":"なんだか君が別人みたいにキレイに見える。あっ、いつもそうなんだけど、特別っていうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_5#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳的声音、气味和体温……我全都喜欢。妳的一切我都喜欢！","en":"Your voice, your scent, your warmth... I like it all. When it comes to you, anything goes!","ja":"声も、匂いも、ぬくもりも……全部が好きなんだ君のものなら、全部!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_6#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我忘不了第一次见到妳的那一刻。从那时候开始，我就喜欢上妳了。","en":"I'll never forget the day we met. I've had a special place for you in my heart since then.","ja":"最初に君に会った時のこと忘れないよ。あの時からボクは君がずっと好きだったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_7#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我玩过不少游戏，但我现在之所以会玩《ALO》，肯定是命运的指引。","en":"I've played my fair share of games, but I think it's fate that brought me to ALO.","ja":"いろんなゲームをやったけど今《ALO》をプレイしてるのってきっと運命なんだって思う"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_8#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嘿嘿，我们的脸贴得好近！我是不是脸红了？真难为情啊。","en":"Hehehe, not so close! You're making me blush. Can't you tell?","ja":"えへへ、こんなに顔が近いよ!ボク、顔赤くなってるでしょなんだか照れちゃうよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_yuuki_alo_sleeping_9#originalText","id":"talk.vc.home_wait_yuuki_alo_sleeping_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……要是能永远永远一直这样就好了。永远、永远……","en":"I wish we could just stay like this forever and ever... Forever and ever and ever...","ja":"……このまま、ずっとずっとこうやっていられたらいいなずっと、ずうっと……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳摸我头发的时候好温柔……我眼泪都快流出来了。","en":"Your hand on my hair is so terribly gentle... I feel like... I'm gonna cry...","ja":"ボクの髪を触る君の手すっごく優しい……なんだか、涙が出ちゃいそう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"被妳摸过的脸颊好烫……不过，我完全没有任何反感。","en":"My cheek is so hot where you touched it...but I don't mind it at all.","ja":"君に触られたほっぺたすごく熱くて……でもぜんぜんイヤじゃないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我们一直在睡觉，结果头发都缠在一起了。不过，我不想弄回去。","en":"We slept for so long that our hair got tangled together. But I don't wanna go back to normal.","ja":"ずっと寝てたから、ふたりの髪の毛が絡まっちゃってるねでも、戻したくないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_4#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳感觉到了吗？我的身体……像是声音、样子、温度还有柔软，希望妳都感受到了。","en":"Hey, can you feel it? The sounds, shapes, warmth, and softness of my body... I hope you can feel it.","ja":"ねえ、君に伝わってる?ボクの体のこと……音や、形や温度柔らかさも、全部伝わってるといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_5#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"被这样对待，我……会越来越喜欢妳，这样也没关系吗？","en":"If you keep doing that... I'll only crush harder on you. You okay with that?","ja":"そんな風にされたら、ボク……もっともっと好きになっちゃうよそれでもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_6#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我以前曾经希望自己更壮、更有点肌肉……但我现在觉得这样就足够了。","en":"I used to wish I were big and muscular... But now I'm happy with the body I've got.","ja":"もっと大きくて、筋肉質な体に憧れたこともあったけど……今は、この体で良かったって思う"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_7#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我们的手像这样一起比圈圈……有一种和妳心连心的感觉。","en":"When we make a ring with our hands like this...I really feel connected to you.","ja":"君の手とボクの手、こうやって輪っかを作って……こうすると君とつながってるって気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_alo_sleeping_8#originalText","id":"talk.vc.home_touch_yuuki_alo_sleeping_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"啊……！……没关系，我并不讨厌。是妳的话，我随时欢迎……","en":"Oh! No...I didn't mind. I'm cool with anything... as long as you are.","ja":"あっ…………ううん、イヤじゃないよ君なら、ボクはいつでも……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……这不是梦，我现在正和妳躺在一起。嘿嘿，太好了～","en":"So it wasn't a dream... I really am sleeping with you. Hehehe. What a relief!","ja":"……夢じゃなかったボク、君と一緒に寝てるんだえへへ、よかったー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"饭要吃什么好呢？我肚子饿了，不过还不想离开被窝。","en":"What do you wanna do for dinner? I'm hungry, but I don't want to leave.","ja":"ご飯、どうしようか?お腹はすいちゃったけどまだここから出たくないな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_4#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"虽然有点舍不得，不过再不起床真的不行。都已经过中午了。","en":"As much as I hate to, we really should be getting up. It's already past noon.","ja":"ちょっと残念だけどさすがにそろそろ起きないとねもうお昼過ぎちゃったし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_5#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嗯～一直爬不起来耶。那我数到三，我们一起起床吧！","en":"Mmm... It's really hard to get up. Okay, how about we both get up on the count of three?","ja":"うーん、なかなか起きられないなあそれじゃ、「せーの!」で一緒に体を起こそうか!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_7#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"妳要负责准备晚餐吗？太棒了～！我最喜欢妳煮的菜了！","en":"Are you cooking dinner tonight? Yay! I just love your cooking!","ja":"晩ご飯は君が作ってくれるの?やったー!ボク、君のご飯大好き!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_8#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我本来是连睡觉都舍不得的，不过能和妳一起躺着，感觉真的很棒。","en":"I used to think sleep was a waste of time, but sleep seems extra lovely when I'm with you.","ja":"寝る時間はもったいないって思ってたけど、こうしてふたりで寝るのは、素敵だなって感じる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_10#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"就算不紧紧相依，妳的体温也能让我感受到温暖。这样我应该能睡得很好。","en":"Even if we're not snuggling, you still keep me warm. I think I'm gonna get a good night's sleep.","ja":"くっついてなくても、君の体温がボクを温めてくれてるだから、ゆっくり眠れそう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuuki_alo_sleeping_11#originalText","id":"talk.vc.home_time_yuuki_alo_sleeping_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我一直有点期待能和别人在半夜小声聊天。感觉就像是去校外旅行一样。","en":"I've always wanted to have late- night pillow-talk with someone. Like on a school trip.","ja":"夜中、小さい声でお話しするのちょっと憧れてたんだ修学旅行とか、そんな感じ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_day_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"这个星期感觉会发生很棒的事。因为在一周的第一天就能和妳在一起。","en":"I've a feeling good things are gonna happen this week. 'Cause I got to spend all of day one with you!","ja":"今週は素敵なことが起きそうだって、始まりの日に君と一緒にいられたんだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_day_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"平时白天的时候，游戏内的人会比较少，但静悄悄的游戏空间我也很喜欢。","en":"Less people play ALO on school days, but I actually like the playing field when it's quiet.","ja":"平日の昼間はゲーム内の人が少なくなるけど、そういう静かなフィールドも好きなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_day_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"和喜欢的人讨论假日要做什么……光是这样我就很幸福了！","en":"Making vacation plans with someone I like... I never knew how blissful that could feel!","ja":"好きな人と、お休みの予定を話す……これだけで、すっごく幸せなんだね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_alo_sleeping_4#originalText","id":"talk.vc.home_day_yuuki_alo_sleeping_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我还可以继续待在这里吗？那么……我们再靠近一点聊天吧。","en":"Hey, can I stay here a bit longer? Okay, then...let's cuddle and talk some more!","ja":"ねえ、まだここにいていいの?だったら……もうちょっとくっついて、おしゃべりしようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"俗话说「一年之计在于元旦」，这就表示我们今年能一直在一起，对吧？","en":"They say New Year's Day sets the tone for the year, so I'll get to spend the whole year with you!","ja":"一年の計は元旦にありって言うから、今年は君とずっと一緒にいられるってことだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我其实不太想把鬼赶出去。因为鬼搞不好也有自己的苦衷啊。","en":"I don't want to exorcise demons. I mean, not all demons are evil. Many have their reasons...","ja":"ボクは、鬼は外ってあんまり言いたくないんだ。鬼の人だって事情があるかもしれないでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"有能送情人节巧克力的人是一件很幸福的事情。当然……是本命巧克力。","en":"I love having a person to give Valentine's chocolates to. They're true-love chocolates, of course.","ja":"バレンタイン、あげたいと思う人がいるって幸せだなもちろん……本命だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_4#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天是女孩子的节日，我们就两个人一起庆祝吧！要不要换上和服？","en":"Since Hinamatsuri is a girls' festival, let's celebrate it together! Wanna like, wear kimono?","ja":"今日は女の子の節句だからボクたちふたりともお祝いだね!お着物とか、着てみる?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_5#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我们连情人节的回礼都一样耶。要是能每年都交换礼物的话，我……会很开心的。","en":"Look, we both gave each other White Day gifts! I'd sure love to do this every year...","ja":"お返しもふたりで一緒だねこうやって、毎年交換できたらボク……うれしいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_6#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……不行，我想了很久，还是觉得就算是愚人节，也没办法对妳说谎！","en":"It's no use... I've done a lot of thinking, but I just can't lie to you! Not even on April Fool's.","ja":"……ダメだ、いろいろ考えたけどエイプリルフールだとしても君に嘘はつけないよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_7#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"黄金周有很多想做的事情，但和妳在一起我就满足了。","en":"I wanted to do a lot of stuff on Golden Week, but I'm cool with whatever as long as it's with you.","ja":"ゴールデンウィークはいろいろやりたいなって思ってたけど君と一緒ならそれだけでいいや"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_8#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"雨天的时候，皮肤的触感真的会不太一样耶。来，妳摸摸看。","en":"You know, my skin always feels a little different on rainy days. Here, touch it.","ja":"雨の日は、やっぱりちょっと肌の感じとか変わるよねほら、触ってみて"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_9#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"繁星的故事……如果有游戏使用那种世界观，我想和妳一起去玩玩看。","en":"If there were a VR game with a Tanabata setting, I'd love to play it with you.","ja":"星たちの物語……そんな世界を舞台にしたゲームがあったらボク、君と一緒に行ってみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_10#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"好想和妳一起参加夏季祭典喔。我想尽情品尝炒面和刨冰！","en":"I'd love to see what a summer festival is like. I'd eat all the yakisoba and shaved ice!","ja":"夏祭りって行ってみたいな焼きそばとかかき氷、いっぱい食べてみたい!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_11#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"假期就要在今天结束了……好期待下次放假喔。想再和妳一起享受悠闲的时光！","en":"Summer vacation ends today... The next one can't come soon enough! I wanna chill with you again.","ja":"今日でお休みも終わりだね……次のお休みが待ち遠しいなまたふたりでのんびりしたい!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_12#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_12","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我从没看过这么大的月亮。是不是和妳一起，所以才看起来特别大？","en":"I've never seen the moon this big before. Maybe it looks extra big because I'm with you?","ja":"こんなに大きい月は初めて君と一緒だから、特別大きく見えるのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_13#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_13","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我已经准备好糖果了，这样就能分给上门的孩子们啰。妳看，有很多喔！","en":"I've got candy on standby in case any kids show up. See? I've got tons of it!","ja":"いつ子どもたちが来てもいいように、お菓子を準備してあるんだ。ほら、たくさんあるよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_14#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_14","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我不太清楚妳在《SAO》的过往……不过我很庆幸妳活了下来。","en":"I don't know much about what happened in SAO...but I really am glad you made it out.","ja":"《SAO》の中のことはよく知らないけど……君が生きててくれて、ホントよかった"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_alo_sleeping_15#originalText","id":"talk.vc.home_event_yuuki_alo_sleeping_15","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我认为圣诞老公公真的存在。因为妳在这里，对我来说就是最棒的礼物。","en":"I think Santa actually does exist. I mean, I have you! The best present I could ever ask for.","ja":"サンタさんって、きっとホントにいると思う。だって、君がここにいることが、素敵なプレゼントだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"竟然能和妳一起过生日！我觉得……心中充满了感动。谢谢，我最喜欢妳了。","en":"Look at me, with you on my birthday! Ugh… My heart is so full it hurts. Thanks. I love you.","ja":"誕生日に君と一緒なんてボク……なんか胸がいっぱいだよありがとう、大好き"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天是桐人的生日对吧。我也可以……一起去帮他庆祝吗？","en":"It's Kirito's birthday today. Do you think...I can come to the party?","ja":"今日はキリトの誕生日だねボクも……一緒にお祝いしても、いいかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_6#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"生日快乐！妳好像变得比昨天更漂亮了！","en":"Happy Birthday! Is it just me, or are you even more beautiful than you were before?!","ja":"誕生日おめでとう!なんか、昨日より一段とキレイになったよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_7#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"既然是莉法的生日，那得到风精灵领地去才行！办一个盛大的派对吧！","en":"For Leafa's birthday, we'd better go to Sylph territory! Let's throw a big bash for her!","ja":"リーファの誕生日だったらシルフ領に行かないと!おっきなパーティーやろう!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_8#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"难得诗乃来到了《ALO》，大家一起帮她庆祝吧！","en":"Hey, Sinon came all the way to ALO to hang out—let's throw her a big party with the gang!","ja":"せっかくシノンが《ALO》に来てくれたんだからみんなでお祝いしようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_14#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_14","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"莉兹的生日，我们要不要一起合送她礼物？","en":"Wanna give Liz a birthday present from both of us?","ja":"リズの誕生日はふたりでなにか一緒にプレゼントしない?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_alo_sleeping_15#originalText","id":"talk.vc.home_bd_yuuki_alo_sleeping_15","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"西莉卡的生日该送什么好呢？一起想想看吧。","en":"What should I get Silica for her birthday? Come brainstorm with me.","ja":"シリカの誕生日はなにがいいかなあふたりで考えよう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_alo_sleeping_1#originalText","id":"talk.vc.home_etc_yuuki_alo_sleeping_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"活动已经通关了吗！？妳该不会是……为了和我共处，才那么努力……？","en":"Whoa, you already cleared the event?! Wait... Did you speed through it so you could be with me?","ja":"もうイベントクリアしたの!?もしかして……ボクと過ごすために頑張ってくれたり……?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_alo_sleeping_2#originalText","id":"talk.vc.home_etc_yuuki_alo_sleeping_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"咦，我可以看吗？那不是给妳的礼物吗？","en":"Huh? You don't mind if I open it? But it's a present for you.","ja":"え、ボクが見てもいいの?君宛のプレゼントなのに"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_alo_sleeping_3#originalText","id":"talk.vc.home_etc_yuuki_alo_sleeping_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"要不要一起参加下次的活动？只要我们两个一起，一定会是最快通关的人。","en":"Wanna do the next event with me? If we work together, I'm sure we could be the first to clear.","ja":"次のイベント、一緒に参加しようかボクたちふたりなら、きっと一番でクリアできるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_1#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"我的歌声一定会传到需要这歌声的人的心里。","en":"My voice will resonate in the hearts of those who need it!","ja":"私の歌声はそれを必要としている人の心に必ず届くわ"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_2#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"我会像这样一直待在你身边的，所以你放心吧。","en":"I'll always be by your side, just like this! So don't worry.","ja":"こうしてずっとそばにいるわだから安心してね"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_3#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"我很喜欢粉红色的衣服喔。你不觉得跟我的头发和眼睛颜色很搭吗？","en":"I like my clothes to be pink! Don't you think they go with the color my hair and eyes?","ja":"私ピンクのお洋服って好きよ髪や瞳の色と相性がいいと思わない?"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_4#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"呐呐，我们现在一起去远一点的地方好不好？说不定会有美好的相遇喔！","en":"Hey! How about we go somewhere far for a change? There's probably someone special just waiting for us!","ja":"ねえねえ、今からちょっと遠くまで出かけてみない?何か素敵な出会いがあるかも!"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_5#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_5","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"你就是我的MVP！","en":"You are my MVP!","ja":"あなたが私の、MVP!"},"kind":"dialogue"},{"uid":"talk.vc.home_yuna_alo_pixie_wait_6#originalText","id":"talk.vc.home_yuna_alo_pixie_wait_6","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"就只唱给你听喔。我珍藏的情歌！","en":"No one but you can listen to this! My love song!","ja":"あなただけに聞かせてあげるとっておきの、ラブソング!"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_wait_1#originalText","id":"talk.vc.home_lipia_pajamas_wait_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"请问有我帮得上忙的事吗？阁下，请随便吩咐。","en":"Would there happen to be anything I could do? Please ask if you need anything.","ja":"私に出来ることはありませんか?閣下、なんなりとお申し付けください"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_wait_2#originalText","id":"talk.vc.home_lipia_pajamas_wait_2","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"那个……阁下我可以去您的身边吗……","en":"Would... It be ok if I stay by your side?","ja":"あの……閣下お側に行っても良いでしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_touch_1#originalText","id":"talk.vc.home_lipia_pajamas_touch_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"我的性命和身体，早就奉献给阁下您了。","en":"I will offer my life and body for you.","ja":"この命も、体もとうに閣下に捧げています"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_touch_2#originalText","id":"talk.vc.home_lipia_pajamas_touch_2","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"这种服装虽然害羞，但要是您喜欢的话我会很开心的……","en":"I am embarrassed to be in such an outfit, but if it's to your liking, then I'm happy...","ja":"こんな格好は気恥ずかしいのですがお気に召していただけましたら嬉しいです……"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_touch_4#originalText","id":"talk.vc.home_lipia_pajamas_touch_4","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下的手碰到的部份，传来了幸福的感觉。那个，要是可以的话，请更多的……","en":"I think I can just sink into happiness from the spot where your hand touched me. If you wouldn't mind, just a little more...","ja":"閣下のお手が触れた部分から幸せが染まっていくようですあの、よければもっと……"},"kind":"dialogue"},{"uid":"talk.vc.home_lipia_pajamas_touch_5#originalText","id":"talk.vc.home_lipia_pajamas_touch_5","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"啊……像那样触碰的话，那个，我会无法保持冷静的……","en":"If you touch me like that I won't be able to keep calm...","ja":"あっ……そのように触れられるとえっと、落ち着かなくなってしまいますから……"},"kind":"dialogue"},{"uid":"talk.vc.home_renri_integrator_2021_aug_wait_1#originalText","id":"talk.vc.home_renri_integrator_2021_aug_wait_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"要、要是你愿意的话，要不要下次一起乘着风缝出远门去玩……?","en":"M-Maybe next time, we could ride Kazenui and go somewhere... far away?","ja":"よ、よかったら今度風縫に乗って一緒に遠出してみない……?"},"kind":"dialogue"},{"uid":"talk.vc.home_renri_integrator_2021_aug_touch_1#originalText","id":"talk.vc.home_renri_integrator_2021_aug_touch_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"可、可以也摸摸看你的头发吗……？","en":"C-Could I touch y-your hair?","ja":"き、君の髪にも触れていいかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_renri_integrator_2021_aug_touch_2#originalText","id":"talk.vc.home_renri_integrator_2021_aug_touch_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"从刚才开始我的心脏就加速大力的跳动……这是为何呢？","en":"M-My heart just skipped a beat... I wonder what that was...","ja":"さっきから僕の心臓が大きく波打つんだ……なんでかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_1#originalText","id":"talk.vc.home_wait_eugeo_integrator_1","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"那个人会给我想要的东西， 我只要这样就满足了。","en":"That person will give me what I want. For me, that's all I need.","ja":"あの人は僕の欲しいものをくれるんだ僕にはもう、それだけで充分なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_2#originalText","id":"talk.vc.home_wait_eugeo_integrator_2","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"我不知道，也不想知道。不论是你⋯⋯还是其他人，我都受够了⋯⋯","en":"I don't know and I don't want to know. I hate... you and everybody...","ja":"知らない。知りたくない君のことも……誰かのことも嫌なんだ、もう…………のは…………"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_3#originalText","id":"talk.vc.home_wait_eugeo_integrator_3","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"我的头⋯⋯好痛⋯⋯只要想想起一些事我的头就会非常痛。","en":"My head... it hurts... I get a terrible headache whenever I try to remember anything.","ja":"頭が……痛い……何かを思い出そうとするとひどい頭痛がするんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_4#originalText","id":"talk.vc.home_wait_eugeo_integrator_4","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"我跟你没什么好说的。因为我必须跟你战斗。","en":"There's nothing more to discuss about. Because I will not fight you.","ja":"これ以上話すことはないよ君とは戦わなくちゃならないんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_9#originalText","id":"talk.vc.home_wait_eugeo_integrator_9","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"……为什么你的眼神总是那么悲伤？我和你，明明是敌人。","en":"...Why do you have such a  sad look in your eyes? Even though you are my enemy.","ja":"……どうして君の瞳はそんなに悲しそうなんだ？僕と君は、敵同士なのに"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_1#originalText","id":"talk.vc.home_touch_eugeo_integrator_1","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"⋯⋯抱歉，我不认识你。","en":"...I'm sorry. I don't know who you are.","ja":"……ごめんよ、君のことは知らない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_2#originalText","id":"talk.vc.home_touch_eugeo_integrator_2","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"你不要再碰我了。被你触碰……我总觉得有点奇怪。","en":"Don't touch me anymore! For some reason... I feel strange when you do.","ja":"それ以上触らないで君に触られると、なんだか……妙な感じがするから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_3#originalText","id":"talk.vc.home_touch_eugeo_integrator_3","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"额头深处感觉有一个洞，但只要想去看看那个洞，心里就会觉得很痛……","en":"A hole is open at the very back of my head. Whenever I try to peer into it, my chest tightens...","ja":"額の奥に、穴が開いているんだでもそこを覗こうとすると胸が締め付けられる……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_4#originalText","id":"talk.vc.home_touch_eugeo_integrator_4","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"⋯⋯Remove core protection","en":"...Remove Core Protection","ja":"……リムーブ・コア・プロテクション"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_5#originalText","id":"talk.vc.home_touch_eugeo_integrator_5","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"真不可思议……从你身上我感受不到敌意。","en":"Strange... I don't feel like you are my enemy.","ja":"不思議だ……君からは敵意を感じない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_1#originalText","id":"talk.vc.home_time_eugeo_integrator_1","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"又迎来早晨了……真希望我能一直在黑暗中昏睡。","en":"It's morning again... I wish I could stay in a daze within the darkness.","ja":"また朝がきた……暗い闇の中でずっとまどろんでいたい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_4#originalText","id":"talk.vc.home_time_eugeo_integrator_4","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"好了，已经够了吧。你是为了和我战斗而来到这里的吧？","en":"Shall we start? That's why you're here, right? To fight me.","ja":"さあ、もういいじゃないか君は僕と戦うためにここにいるんだろう？"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_7#originalText","id":"talk.vc.home_time_eugeo_integrator_7","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"日落西沉……要快点回到那个人的身边去。","en":"Nightfall... I must return to where that person is.","ja":"日が沈む……あの人のところへ帰らなくちゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_10#originalText","id":"talk.vc.home_time_eugeo_integrator_10","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"我会做梦……梦见看自己和一个不认识的男孩和不认识的女孩一起……","en":"I dream... That I'm together with a boy and girl whom I don't know...","ja":"夢を見るんだ……知らない男の子と知らない女の子が、一緒に……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_integrator_1#originalText","id":"talk.vc.home_etc_eugeo_integrator_1","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"按照命令完成了呢。恭喜你。那个人一定会称赞你的。","en":"Looks like mission accomplished. Congratulations. That person will definitely praise you for sure. ","ja":"命令を遂行したんだねおめでとうきっとあの人も褒めてくれるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_integrator_2#originalText","id":"talk.vc.home_etc_eugeo_integrator_2","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"是礼物。……你一定被很多的人爱着吧。","en":"It's a present. ...You are really are loved by many people it seems.","ja":"贈り物だよ……きっと君は、いろんな人に愛されているんだろうね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_integrator_3#originalText","id":"talk.vc.home_etc_eugeo_integrator_3","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"有新的命令。要快点完成任务才行。一切都是为了那个人。","en":"A new order just came in. You need to complete your mission. Everything for that person.","ja":"新しい命令が下されたよ任務を終わらせないとすべてはあの人のために"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_1#originalText","id":"talk.vc.home_yui_sao_valentine_wait_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸！今天请跟我约会！","en":"Papa! Let's go on a date today!","ja":"パパ!今日は私とデートしてくださいっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_2#originalText","id":"talk.vc.home_yui_sao_valentine_wait_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"请尝尝这个点心！这是我跟妈妈一起做的，很好吃喔！","en":"Here's a cake! I made it with Mommy, so it must be delicious!","ja":"お菓子をどうぞ!ママと一緒に作ったのですごくおいしいですよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_3#originalText","id":"talk.vc.home_yui_sao_valentine_wait_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"外国的情人节不一定是送点心，有些地方的情人节是跟重要的人互送礼物的日子。","en":"In many countries, Valentine's day is a day where people give many different kinds of presents, not just cakes, to those who are special to them.","ja":"諸外国のバレンタインはお菓子に限らず、様々なプレゼントを大切な人に贈り合う日なんですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_4#originalText","id":"talk.vc.home_yui_sao_valentine_wait_4","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"被香甜的气味包围着就会觉得很幸福呢。","en":"Happiness is like a good sweet smell!","ja":"甘くて良い匂いに包まれてるとなんだか幸せな気持ちになりますね"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_5#originalText","id":"talk.vc.home_yui_sao_valentine_wait_5","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸！请看这个！我穿上了很可爱的衣服喔！","en":"Papa! Looky here! Look at how cute this outfit is!","ja":"パパ! 見てください!すごく可愛いお洋服を着せてもらっちゃいました!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_valentine_wait_6#originalText","id":"talk.vc.home_yui_sao_valentine_wait_6","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"希望爸爸和妈妈可以一直都幸福快乐。","en":"I hope that Mommy and Daddy will always be happy!","ja":"パパとママがずーっと幸せでありますように"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_2021_sep_wait_1#originalText","id":"talk.vc.home_yui_sao_2021_sep_wait_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"妈妈和爸爸都好漂亮……一定会成为个非常棒的结婚典礼的！","en":"Mommy and Daddy both look so stunning together... The wedding will be so beautiful!","ja":"ママもパパもすごく綺麗……素敵な結婚式になりますね!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_2021_sep_wait_2#originalText","id":"talk.vc.home_yui_sao_2021_sep_wait_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸！要让妈妈幸福哦！当然，爸爸也要幸福才行哦！","en":"Please keep Mommy happy, Daddy! And of course, your happiness counts too!","ja":"パパ! ママを幸せにしてあげてくださいね。もちろんパパも幸せにならなきゃだめです!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_2021_sep_touch_1#originalText","id":"talk.vc.home_yui_sao_2021_sep_touch_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"嘿嘿……最喜欢让爸爸摸摸头了！","en":"Hehe. I love it when Daddy pets my head!","ja":"えへへパパになでてもらうの大好きです"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_wait_1#originalText","id":"talk.vc.home_yui_sao_sweater_wait_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"今天要和妈妈3个人一起去散步呢！好期待呀！","en":"Today, the three of us get to go on a walk! I can't wait!","ja":"今日はママと3人で、お散歩に行くんですよね! 楽しみです!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_wait_2#originalText","id":"talk.vc.home_yui_sao_sweater_wait_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"只要和爸爸还有妈妈牵着我的手，就会自然地扬起嘴角呢～","en":"Holding hands with Daddy and Mommy puts a smile on my face!","ja":"パパとママが手を繋いでくれると自然と笑顔になっちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_touch_1#originalText","id":"talk.vc.home_yui_sao_sweater_touch_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我也想要摸摸爸爸的头！爸爸请蹲下！","en":"I want to pet Daddy's head too! Crouch down! ","ja":"パパにもなでなでしたいのでしゃがんでください!"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_touch_2#originalText","id":"talk.vc.home_yui_sao_sweater_touch_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"昨天呀，和妈妈一起洗澡，妈妈帮我洗了头发哦！我的头发是不是也像妈妈的一样柔顺漂亮呢？","en":"Yesterday, I took a bath with Mommy and she washed my hair! Is my hair silky like hers?","ja":"昨日、ママとお風呂に入って髪を綺麗に洗ってもらったんですよママみたいにサラサラですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_touch_3#originalText","id":"talk.vc.home_yui_sao_sweater_touch_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"只要和爸爸、妈妈在一起，这里就会变得好温暖。","en":"I get so flustered when I'm here with Daddy and Mommy.","ja":"パパとママと一緒にいるとここが暖かくなります"},"kind":"dialogue"},{"uid":"talk.vc.home_yui_sao_sweater_touch_4#originalText","id":"talk.vc.home_yui_sao_sweater_touch_4","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸！请把我背在肩上！","en":"Daddy! I want a piggyback ride!","ja":"パパ! 肩車してください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_os_1#originalText","id":"talk.vc.home_wait_leafa_os_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"Ordinal Scale里的话，我是不会输给哥哥的！","en":"If it's on Ordinal Scale, then Kirito can't lose!","ja":"オーディナルスケールでならお兄ちゃんにだって負けないよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_os_2#originalText","id":"talk.vc.home_wait_leafa_os_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"这个跟VR不一样，需要用到身体来操作，这样平常的锻炼就变得很重要了。","en":"It's different from VR because you really need to use your body. Daily training is essential.","ja":"VRと違って本当に体を使うから日頃のトレーニングが大切なんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_os_1#originalText","id":"talk.vc.home_touch_leafa_os_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"现实的话，我觉得短头发比较方便行动……哥哥喜欢短头发还是长头发？","en":"In the real world, shorter hair is easier to move around with... Which one do you prefer, Kirito?","ja":"現実だと髪は短い方が動きやすいんだけど……お兄ちゃんはどっちが好き?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_os_4#originalText","id":"talk.vc.home_touch_leafa_os_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"什么？想跟我比试剑道吗？","en":"What? Do you want to do a kendo match?","ja":"なあに?剣道で手合わせしたいの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_os_5#originalText","id":"talk.vc.home_touch_leafa_os_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"最近有点胖了……在VR的世界里明明体型是不会变的……","en":"I've gotten a little bigger lately... Even though my body doesn't change inside VR...","ja":"最近ちょっと太ったかなあ……VRの中なら、体型は変わらないのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_os_1#originalText","id":"talk.vc.home_time_leafa_os_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"Augma在早上锻练的时候也很方便喔。可以登录练习项目，也可以帮忙管理健康。","en":"Augma is convenient even for morning exercise. You can register a menu and even monitor your own body!","ja":"オーグマーは朝練でも便利だよメニューとか登録できるし体調管理もしてくれるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_os_4#originalText","id":"talk.vc.home_time_leafa_os_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"积蓄了Ordinal Scale点数的话，午餐就出去外面吃吧！","en":"I've saved up some Ordinal Scale points, so let's go out for lunch!","ja":"オーディナルスケールのポイント貯まったからお昼は外に食べに行こうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_os_7#originalText","id":"talk.vc.home_time_leafa_os_7","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"明天好像天气会很好！哥哥，我们一起去锻炼吧！","en":"I heard the weather is going to be great tomorrow! Let's go train together, Kirito!","ja":"明日はお天気だって!お兄ちゃん、一緒にトレーニングしようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_os_10#originalText","id":"talk.vc.home_time_leafa_os_10","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哥哥你还不睡吗？那要不要一起出去外面走走？","en":"Are you still awake, Kirito? If you are, how about we go out somewhere?","ja":"まだ寝ないの、お兄ちゃんだったら、ちょっとだけ一緒にお出かけする?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_os_1#originalText","id":"talk.vc.home_day_leafa_os_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天开始又要上学了～哥哥，就只有今天，可以骑车送我上学吗？","en":"One week of school, starting today. Kirito, could you drop me off on your bike, just for today?","ja":"今日から1週間学校かあお兄ちゃん、今日だけバイクで送ってくれない?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_os_2#originalText","id":"talk.vc.home_day_leafa_os_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"学校里戴Augma的人也变多了！好像很流行喔。","en":"Even at school there's a lot of people wearing an Augma! Looks like it's getting very popular.","ja":"学校でもオーグマーつけてる人増えてきてるね!すっごく流行ってるみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_os_3#originalText","id":"talk.vc.home_day_leafa_os_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"难得今天放假，我们就久违地跟家人一起渡过吧。","en":"Since today's a holiday, let's spend some time together with the family.","ja":"今日はお休みだから久しぶりに家族水入らずで過ごそうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_os_4#originalText","id":"talk.vc.home_day_leafa_os_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"在Augma看到日期变成星期一的那一瞬间，我就会觉得很痛苦……","en":"Whenever the date becomes a Monday, it's such a pain.","ja":"オーグマーで日付が月曜日になる瞬間ってなんかすごく辛いの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_os_1#originalText","id":"talk.vc.home_season_leafa_os_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"只有在赏花的时候，我会想放下Augma用自己的眼睛去看樱花。","en":"When it's that time of the year to see the cherry blossoms, I want to take off my Augma and see them with my own eyes.","ja":"お花見をする時くらいはオーグマーを外して自分の目で桜を見たいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_os_2#originalText","id":"talk.vc.home_season_leafa_os_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"在海边戴着Augma游泳的话，应该会坏掉吧。","en":"Swimming in the ocean with your Augma will definitely break it.","ja":"海水浴でオーグマー着けて泳いだらやっぱり壊れちゃうかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_os_3#originalText","id":"talk.vc.home_season_leafa_os_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"秋天有很多美味的诱惑……也能积蓄很多Ordinal Scale的点数。","en":"There are so many temptations in the fall... Just think of the amount of Ordinal Scale points you can save up!","ja":"秋は美味しい誘惑が多くて……オーディナルスケールのポイントもたくさん貯まるし"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_os_4#originalText","id":"talk.vc.home_season_leafa_os_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"AR的话，冬天会很难行动呢。因为大家都穿着很多衣服。","en":"It's difficult to move around during the winter in AR. For example, everyone's wearing to many layers!","ja":"ARだと、冬は動きづらいよねみんな厚着しているし"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_wait_1#originalText","id":"talk.vc.home_leafa_real_school_wait_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哥哥，东西都记得带了吗？因为你意外地很迷糊。","en":"You can be pretty absent-minded sometimes, you know, so make sure you didn't forget anything!","ja":"お兄ちゃん忘れ物ない?案外おっちょこちょいなんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_wait_2#originalText","id":"talk.vc.home_leafa_real_school_wait_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我也想和哥哥去同一所学校上学啊……","en":"I wanted to go to the same school as you...","ja":"あたしもお兄ちゃんと同じ学校に行きたかったなぁ……"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_wait_3#originalText","id":"talk.vc.home_leafa_real_school_wait_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"机会难得，要不要顺路去哪逛逛？下课后去约会吧！","en":"Now that it's just us, why don't we go somewhere for an after-school \"date\"?","ja":"せっかくだからどこかに寄って行かない? 放課後デートしよ"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_touch_1#originalText","id":"talk.vc.home_leafa_real_school_touch_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哥哥你很会摸摸头耶！","en":"You're pretty good at this whole head pat thing, big bro.","ja":"お兄ちゃん頭撫でるの上手だよね"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_touch_2#originalText","id":"talk.vc.home_leafa_real_school_touch_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"咦……穿制服也很明显吗……？就叫你不要再看了啦……","en":"What? Even when I'm in my uniform I stand out in a crowd? Stop making me feel all embarrassed!","ja":"ええぇ……制服でも目立つ……?あんまり見ないでってばぁ……"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_real_school_time_1#originalText","id":"talk.vc.home_leafa_real_school_time_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哥哥等我一下啦！我不是说因为今天没有晨练，所以可以一起走一段路嘛～","en":"What?! You said you didn't have any practice this morning so you could walk with meeee!","ja":"お兄ちゃん待ってよー!今日は朝練無いから、途中まで一緒に行こうって言ったじゃん〜"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_os_swim_wait_1#originalText","id":"talk.vc.home_leafa_os_swim_wait_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"就、就只有我穿学校的泳衣，太、太令人害羞了啦……","en":"I'm the only one here in my school swimsuit... T-This is...","ja":"あ、あたしだけスクール水着なんては、恥ずかしいよお……"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_os_swim_touch_1#originalText","id":"talk.vc.home_leafa_os_swim_touch_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我不会泳游，可别把我当笨蛋哦。","en":"I said I can't swim! So don't be making fun of me.","ja":"泳げないからって馬鹿にしないでね"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_os_swim_touch_2#originalText","id":"talk.vc.home_leafa_os_swim_touch_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"啊啊！等、等一下哥哥！住、注意一点啦……刚刚，碰到了……","en":"Ack! H-Hey Kirito! Careful there...that just hit me!","ja":"んあっ!ちょ、ちょっとお兄ちゃん!き、気をつけてよ……今、あたった"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_suguha_1st_1#originalText","id":"talk.vc.home_wait_suguha_1st_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"欸，偶尔跟我一起训练嘛。试试看，会很好玩的喔。","en":"Come on, let's practice together for a change! It'll be fun, I promise.","ja":"ねえ、たまには一緒に稽古やろうよやってみたら楽しいよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_suguha_1st_2#originalText","id":"talk.vc.home_wait_suguha_1st_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我也去考机车驾照好了……这样一来就能一起骑车了。","en":"Maybe I should get a motorcycle license, too. Then we could ride together!","ja":"あたしもバイクの免許取ろうかなあそうしたら、一緒に乗れるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_suguha_1st_3#originalText","id":"talk.vc.home_wait_suguha_1st_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"你老是勉强自己，很让人担心耶。拜托你多依赖我一点啦。","en":"You always overwork yourself and it seriously worries me. You should let me help out more.","ja":"君はいっつも無理してるからちょっと心配だよもっと、あたしを頼ってね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_suguha_1st_4#originalText","id":"talk.vc.home_wait_suguha_1st_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我还是觉得能够飞上天的世界最好玩了～","en":"I really do think I prefer a world where you can fly.","ja":"あたしはやっぱり、飛ぶことができる世界が楽しいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_suguha_1st_9#originalText","id":"talk.vc.home_wait_suguha_1st_9","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"哈啰～你醒着吗？如果累了要好好休息喔。","en":"Hellooo? Are you awake? If you're tired, you should really let yourself rest.","ja":"もしもーし、起きてる?疲れちゃったならちゃんと休んでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1st_1#originalText","id":"talk.vc.home_touch_suguha_1st_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"真是的，动不动就把我当小孩子对待……我已经不是小孩子了啦。","en":"Jeez, why do you always have to treat me like that? I'm not a baby anymore, you know.","ja":"もう、すぐそうやって子ども扱いして……あたし、もう子どもじゃないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1st_2#originalText","id":"talk.vc.home_touch_suguha_1st_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"现实世界中的我是短发，所以在VR世界里才会试着留长发。","en":"Since my hair's short IRL, I like having it long in VR.","ja":"リアルだと短いからVRの世界ではちょっと長い髪にしてみたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1st_4#originalText","id":"talk.vc.home_touch_suguha_1st_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"呀！？你、你真是的……不可以这样啦……","en":"Eek! J-Jeez... Seriously. Can you stop doing that?","ja":"ひゃん!?も、もう……そういうのはダメだよ……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1st_5#originalText","id":"talk.vc.home_touch_suguha_1st_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"咦？有脏东西吗？……难道说根本没有脏东西，你却碰了我？","en":"Oh, is it dirty? Unless...you touched it even though it's not dirty?","ja":"あれ、汚れてた?……まさか、汚れてもないのに触ったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1st_6#originalText","id":"talk.vc.home_touch_suguha_1st_6","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"嗯，你叫我？我现在要去准备，等我一下喔。","en":"Hm, you called me? Sit tight, just gonna get ready.","ja":"ん、呼んだ?今準備するからちょっと待ってて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_suguha_1st_1#originalText","id":"talk.vc.home_time_suguha_1st_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"身体已经习惯晨练了，所以会不由自主地早起呢。","en":"I've gotten so used to morning practice that I always just wake up early.","ja":"朝練が習慣になっててどうしても早めに目が覚めちゃうんだよ"},"kind":"dialogue"}]};
